package ui

import "html/template"

// AdminWorkbenchDashboardCSS is the structural layer for the Workbench. It
// intentionally owns layout, hierarchy, and interaction states separately
// from the palette tokens in AdminWorkbenchCSS.
const AdminWorkbenchComponentsCSS = `html[data-ui-theme="workbench"] .wb-dashboard{display:grid;gap:14px;max-width:1600px;margin:0 auto}html[data-ui-theme="workbench"] .wb-command-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding-bottom:10px;border-bottom:1px solid var(--line)}html[data-ui-theme="workbench"] .wb-breadcrumb{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:.76rem;font-weight:600}html[data-ui-theme="workbench"] .wb-breadcrumb strong{color:var(--ink);font-weight:700}html[data-ui-theme="workbench"] .wb-breadcrumb svg{width:12px;height:12px;opacity:.7}html[data-ui-theme="workbench"] .wb-command-actions{display:flex;align-items:center;gap:6px}html[data-ui-theme="workbench"] .wb-command-actions .button{min-height:30px;height:30px;padding:0 10px;font-size:.76rem;border-radius:var(--radius-md);font-weight:600}html[data-ui-theme="workbench"] .wb-hero{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(280px,.7fr);gap:16px;position:relative;padding:16px 20px;border:1px solid var(--line);border-radius:var(--radius-lg);background:var(--surface);box-shadow:none}html[data-ui-theme="workbench"] .wb-hero-copy{position:relative;z-index:1;max-width:620px}html[data-ui-theme="workbench"] .wb-eyebrow{display:inline-flex;align-items:center;gap:6px;color:var(--brand);font-size:.66rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase}html[data-ui-theme="workbench"] .wb-eyebrow i{width:6px;height:6px;border-radius:2px;background:var(--green);box-shadow:0 0 0 2px var(--green-subtle)}html[data-ui-theme="workbench"] .wb-hero h2{margin:6px 0 4px;font-size:1.35rem;line-height:1.2;letter-spacing:-.03em;font-weight:700}html[data-ui-theme="workbench"] .wb-hero p{max-width:540px;margin:0;color:var(--ink-secondary);font-size:.82rem;line-height:1.5}html[data-ui-theme="workbench"] .wb-hero-steps{position:relative;z-index:1;display:grid;align-content:center;gap:6px}html[data-ui-theme="workbench"] .wb-hero-step{display:grid;grid-template-columns:24px 1fr;align-items:center;gap:8px;padding:8px 10px;border:1px solid var(--line);border-radius:var(--radius-md);background:var(--bg-subtle);text-decoration:none;color:var(--ink);transition:border-color .12s cubic-bezier(.16,1,.3,1),background .12s cubic-bezier(.16,1,.3,1)}html[data-ui-theme="workbench"] .wb-hero-step:hover{background:var(--surface-hover);border-color:var(--brand);color:var(--ink)}html[data-ui-theme="workbench"] .wb-hero-step b{display:grid;place-items:center;width:24px;height:24px;border-radius:var(--radius-sm);background:var(--brand);color:#fff;font:700 .68rem var(--font-mono)}html[data-ui-theme="workbench"] .wb-hero-step strong{display:block;font-size:.76rem;font-weight:600}html[data-ui-theme="workbench"] .wb-hero-step small{display:block;margin-top:1px;color:var(--muted);font-size:.68rem}html[data-ui-theme="workbench"] .wb-metric-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}html[data-ui-theme="workbench"] .wb-metric{display:grid;grid-template-columns:30px 1fr;align-items:center;gap:10px;min-width:0;padding:10px 12px;border:1px solid var(--line);border-radius:var(--radius-md);background:var(--surface);box-shadow:none;transition:border-color .12s cubic-bezier(.16,1,.3,1),background .12s cubic-bezier(.16,1,.3,1)}html[data-ui-theme="workbench"] .wb-metric:hover{border-color:var(--brand);background:var(--surface-hover)}html[data-ui-theme="workbench"] .wb-metric-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:var(--radius-sm);background:var(--bg-subtle);color:var(--brand);border:1px solid var(--line)}html[data-ui-theme="workbench"] .wb-metric-icon svg{width:15px;height:15px}html[data-ui-theme="workbench"] .wb-metric label{display:block;color:var(--muted);font-size:.66rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase}html[data-ui-theme="workbench"] .wb-metric strong{display:block;margin-top:2px;overflow:hidden;color:var(--ink);font:700 1.2rem/1.1 var(--font-mono);text-overflow:ellipsis;white-space:nowrap;letter-spacing:-.02em}html[data-ui-theme="workbench"] .wb-metric small{display:block;margin-top:2px;color:var(--muted);font-size:.66rem}html[data-ui-theme="workbench"] .wb-content-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr);gap:14px;align-items:start}html[data-ui-theme="workbench"] .wb-panel{min-width:0;padding:16px;border:1px solid var(--line);border-radius:var(--radius-lg);background:var(--surface);box-shadow:none}html[data-ui-theme="workbench"] .wb-panel-header{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid var(--line)}html[data-ui-theme="workbench"] .wb-panel-header h3{margin:0;font-size:.9rem;letter-spacing:-.01em;font-weight:700}html[data-ui-theme="workbench"] .wb-panel-header p{margin:2px 0 0;color:var(--muted);font-size:.72rem}html[data-ui-theme="workbench"] .wb-panel-link{display:inline-flex;align-items:center;gap:4px;color:var(--brand);font-size:.72rem;font-weight:700;text-decoration:none}html[data-ui-theme="workbench"] .wb-panel-link svg{width:12px;height:12px}html[data-ui-theme="workbench"] .wb-collection-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}html[data-ui-theme="workbench"] .wb-collection{display:grid;grid-template-columns:28px minmax(0,1fr) 14px;align-items:center;gap:8px;min-width:0;padding:8px 10px;border:1px solid var(--line);border-radius:var(--radius-md);color:var(--ink);text-decoration:none;background:var(--bg-subtle);transition:background .12s cubic-bezier(.16,1,.3,1),border-color .12s cubic-bezier(.16,1,.3,1)}html[data-ui-theme="workbench"] .wb-collection:hover{background:var(--surface-hover);border-color:var(--brand)}html[data-ui-theme="workbench"] .wb-collection-icon{display:grid;place-items:center;width:28px;height:28px;border-radius:var(--radius-sm);background:var(--surface);border:1px solid var(--line);color:var(--brand)}html[data-ui-theme="workbench"] .wb-collection-icon svg{width:14px;height:14px}html[data-ui-theme="workbench"] .wb-collection strong,html[data-ui-theme="workbench"] .wb-collection small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}html[data-ui-theme="workbench"] .wb-collection strong{font-size:.76rem;font-weight:600}html[data-ui-theme="workbench"] .wb-collection small{margin-top:1px;color:var(--muted);font-size:.66rem}html[data-ui-theme="workbench"] .wb-collection>svg{width:12px;height:12px;color:var(--muted)}html[data-ui-theme="workbench"] .wb-side-stack{display:grid;gap:14px}html[data-ui-theme="workbench"] .wb-action-list{display:grid;gap:4px}html[data-ui-theme="workbench"] .wb-action{display:grid;grid-template-columns:26px 1fr 12px;align-items:center;gap:8px;padding:7px 8px;border-radius:var(--radius-md);border:1px solid transparent;color:var(--ink);text-decoration:none;transition:background .12s cubic-bezier(.16,1,.3,1),border-color .12s cubic-bezier(.16,1,.3,1)}html[data-ui-theme="workbench"] .wb-action:hover{background:var(--surface-hover);border-color:var(--line)}html[data-ui-theme="workbench"] .wb-action-icon{display:grid;place-items:center;width:26px;height:26px;border-radius:var(--radius-sm);background:var(--bg-subtle);border:1px solid var(--line);color:var(--brand)}html[data-ui-theme="workbench"] .wb-action-icon svg{width:13px;height:13px}html[data-ui-theme="workbench"] .wb-action strong{display:block;font-size:.76rem;font-weight:600}html[data-ui-theme="workbench"] .wb-action small{display:block;margin-top:1px;color:var(--muted);font-size:.66rem}html[data-ui-theme="workbench"] .wb-action>svg{width:12px;height:12px;color:var(--muted)}html[data-ui-theme="workbench"] .wb-health-list{display:grid;gap:8px;margin:0;padding:0;list-style:none}html[data-ui-theme="workbench"] .wb-health-list li{display:flex;justify-content:space-between;gap:10px;padding-bottom:6px;border-bottom:1px solid var(--line);font-size:.74rem}html[data-ui-theme="workbench"] .wb-health-list li:last-child{padding-bottom:0;border-bottom:0}html[data-ui-theme="workbench"] .wb-health-list span{color:var(--muted)}html[data-ui-theme="workbench"] .wb-health-list strong{color:var(--ink);font-size:.74rem;text-align:right;font-family:var(--font-mono)}html[data-ui-theme="workbench"] .wb-health-state{display:inline-flex;align-items:center;gap:5px;color:var(--green);font-size:.68rem;font-weight:700;padding:2px 7px;border-radius:var(--radius-sm);background:var(--green-subtle);border:1px solid rgba(16,185,129,.25)}html[data-ui-theme="workbench"] .wb-health-state i{width:5px;height:5px;border-radius:1px;background:var(--green)}html[data-ui-theme="workbench"] .wb-empty{padding:14px;border:1px dashed var(--line);border-radius:var(--radius-md);color:var(--muted);font-size:.75rem;text-align:center}@media(max-width:1000px){html[data-ui-theme="workbench"] .wb-hero{grid-template-columns:1fr}html[data-ui-theme="workbench"] .wb-hero-steps{grid-template-columns:repeat(3,minmax(0,1fr))}html[data-ui-theme="workbench"] .wb-content-grid{grid-template-columns:1fr}}@media(max-width:700px){html[data-ui-theme="workbench"] .wb-command-row{align-items:flex-start;flex-direction:column}html[data-ui-theme="workbench"] .wb-command-actions{width:100%}html[data-ui-theme="workbench"] .wb-command-actions .button{flex:1;justify-content:center}html[data-ui-theme="workbench"] .wb-metric-strip{grid-template-columns:repeat(2,minmax(0,1fr))}html[data-ui-theme="workbench"] .wb-collection-grid{grid-template-columns:1fr}html[data-ui-theme="workbench"] .wb-hero{padding:14px}html[data-ui-theme="workbench"] .wb-hero-steps{grid-template-columns:1fr 1fr}html[data-ui-theme="workbench"] .wb-panel{padding:12px}}@media(prefers-reduced-motion:reduce){html[data-ui-theme="workbench"] .wb-metric,html[data-ui-theme="workbench"] .wb-collection,html[data-ui-theme="workbench"] .wb-action{transition:none}}`

var adminWorkbenchDashboardTemplate = template.Must(template.New("admin-workbench-dashboard").Parse(`<div class="wb-dashboard">
<div class="wb-command-row"><div class="wb-breadcrumb"><strong>Studio</strong><span>/</span><span>Genel bakış</span></div><div class="wb-command-actions"><a class="button button-quiet" href="/admin/reports"><span data-studio-icon="reports"></span> Raporları gör</a><a class="button" href="/admin/news/new"><span data-studio-icon="plus"></span> Yeni içerik</a></div></div>
<section class="wb-hero"><div class="wb-hero-copy"><span class="wb-eyebrow"><i></i> Operasyon merkezi</span><h2>Bugün işinizi nereden ilerletelim?</h2><p>İçerik, ticaret ve ekip akışlarını aynı çalışma yüzeyinde izleyin. En sık kullandığınız aksiyonlar tek bir adım uzağınızda.</p></div><div class="wb-hero-steps"><a class="wb-hero-step" href="/admin/news/new"><b>01</b><span><strong>İçerik yayınla</strong><small>Yeni haber veya sayfa oluştur</small></span></a><a class="wb-hero-step" href="/admin/commerce/products#new-product"><b>02</b><span><strong>Kataloğu güncelle</strong><small>Ürün ve stok bilgilerini yönet</small></span></a><a class="wb-hero-step" href="/admin/operations"><b>03</b><span><strong>Sağlığı kontrol et</strong><small>Operasyon sinyallerini incele</small></span></a></div></section>
<section class="wb-metric-strip" aria-label="Sistem özeti"><div class="wb-metric"><span class="wb-metric-icon" data-studio-icon="operations"></span><span><label>Toplam istek</label><strong>{{if .Metrics}}{{.Metrics.TotalRequests}}{{else}}0{{end}}</strong><small>Bu oturum</small></span></div><div class="wb-metric"><span class="wb-metric-icon" data-studio-icon="reports"></span><span><label>Görüntülenme</label><strong>{{if .Metrics}}{{.Metrics.TotalViews}}{{else}}0{{end}}</strong><small>Public ve mağaza</small></span></div><div class="wb-metric"><span class="wb-metric-icon" data-studio-icon="operations"></span><span><label>Yanıt süresi</label><strong>{{if .Metrics}}{{.Metrics.AvgLatencyMS}}{{else}}0{{end}}<small> ms ortalama</small></strong></span></div><div class="wb-metric"><span class="wb-metric-icon" data-studio-icon="security"></span><span><label>Hata oranı</label><strong>{{if .Metrics}}{{.Metrics.TotalErrors}}{{else}}0{{end}}</strong><small>{{if and .Metrics (gt .Metrics.TotalErrors 0)}}İncelenmeli{{else}}Sistem sağlıklı{{end}}</small></span></div></section>
<section class="wb-content-grid"><article class="wb-panel"><div class="wb-panel-header"><div><h3>Çalışma alanları</h3><p>Modülleriniz ve operasyon yüzeyleri</p></div><a class="wb-panel-link" href="/admin/control">Tümünü yönet <span data-studio-icon="arrow"></span></a></div><div class="wb-collection-grid">{{range .Collections}}{{if ne .ID "commerce_variants"}}<a class="wb-collection" href="{{(index .Actions 0).Href}}"><span class="wb-collection-icon" data-studio-icon="folder"></span><span><strong>{{.Label}}</strong><small>{{.Description}}</small></span><span data-studio-icon="arrow"></span></a>{{end}}{{end}}<a class="wb-collection" href="/admin/commerce/orders"><span class="wb-collection-icon" data-studio-icon="orders"></span><span><strong>Siparişler</strong><small>Müşteri ve ödeme akışı</small></span><span data-studio-icon="arrow"></span></a><a class="wb-collection" href="/admin/members"><span class="wb-collection-icon" data-studio-icon="folder"></span><span><strong>Üyeler</strong><small>{{.MemberStats.TotalMembers}} kayıtlı hesap</small></span><span data-studio-icon="arrow"></span></a></div></article><aside class="wb-side-stack"><article class="wb-panel"><div class="wb-panel-header"><div><h3>Hızlı aksiyonlar</h3><p>En sık kullanılan işlemler</p></div></div><nav class="wb-action-list"><a class="wb-action" href="/admin/news/new"><span class="wb-action-icon" data-studio-icon="plus"></span><span><strong>Yeni haber yaz</strong><small>Taslak oluştur ve yayınla</small></span><span data-studio-icon="arrow"></span></a><a class="wb-action" href="/admin/pages/new"><span class="wb-action-icon" data-studio-icon="plus"></span><span><strong>Yeni sayfa ekle</strong><small>Bloklarla içerik oluştur</small></span><span data-studio-icon="arrow"></span></a><a class="wb-action" href="/admin/media"><span class="wb-action-icon" data-studio-icon="media"></span><span><strong>Medya yükle</strong><small>Görsel ve dosyaları düzenle</small></span><span data-studio-icon="arrow"></span></a></nav></article><article class="wb-panel"><div class="wb-panel-header"><div><h3>Çalışma ortamı</h3><p>Son durum</p></div><span class="wb-health-state"><i></i> Sağlıklı</span></div><ul class="wb-health-list"><li><span>Aktif üyeler</span><strong>{{.MemberStats.ActiveMembers}}</strong></li><li><span>Doğrulanmış hesaplar</span><strong>{{.MemberStats.VerifiedMembers}}</strong></li><li><span>Veri kaynağı</span><strong>{{if .DataSource}}{{.DataSource}}{{else}}Proses içi{{end}}</strong></li></ul></article></aside></section></div>`))
